import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, type JobRow } from './db.ts';

const MAX_ATTEMPTS = 3;
const STEP_MS = 100;
const RETRY_DELAY_MS = 500;

const db = openDatabase();
let stopping = false;
let wake: (() => void) | null = null;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
    wake?.();
  });
}

const beatStmt = db.prepare('INSERT INTO heartbeat (id, at) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET at = excluded.at');
function beat(): void {
  try {
    beatStmt.run(Date.now());
  } catch (err) {
    console.error('heartbeat failed', err);
  }
}
beat();
const beatTimer = setInterval(beat, 500);

const now = () => new Date().toISOString();

// Recover jobs left running by a worker that died: the interrupted attempt is re-run.
db.prepare(
  `UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress = 0, run_after = 0, updated_at = ?
   WHERE status = 'running'`,
).run(now());

const claimStmt = db.prepare(
  `UPDATE jobs SET status = 'running', attempts = attempts + 1, progress = 0, updated_at = ?
   WHERE seq = (SELECT seq FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1)
     AND status = 'queued'
   RETURNING *`,
);
const progressStmt = db.prepare(`UPDATE jobs SET progress = ?, updated_at = ? WHERE id = ? AND status = 'running'`);
const completeStmt = db.prepare(
  `UPDATE jobs SET status = 'completed', progress = steps, output = ?, error = NULL, updated_at = ? WHERE id = ? AND status = 'running'`,
);
const retryStmt = db.prepare(
  `UPDATE jobs SET status = 'queued', progress = 0, run_after = ?, updated_at = ? WHERE id = ? AND status = 'running'`,
);
const failStmt = db.prepare(
  `UPDATE jobs SET status = 'failed', progress = 0, output = NULL, error = ?, updated_at = ? WHERE id = ? AND status = 'running'`,
);
const requeueStmt = db.prepare(
  `UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress = 0, run_after = 0, updated_at = ? WHERE id = ? AND status = 'running'`,
);

async function idle(ms: number): Promise<void> {
  if (stopping) return;
  await new Promise<void>((resolve) => {
    const t = setTimeout(() => { wake = null; resolve(); }, ms);
    wake = () => { clearTimeout(t); wake = null; resolve(); };
  });
}

async function processJob(job: JobRow): Promise<void> {
  if (job.attempts <= job.fail_attempts) {
    await sleep(STEP_MS);
    if (job.attempts >= MAX_ATTEMPTS) {
      failStmt.run('transient failure', now(), job.id);
      console.log(`job ${job.id} failed after ${job.attempts} attempts`);
    } else {
      retryStmt.run(Date.now() + RETRY_DELAY_MS, now(), job.id);
      console.log(`job ${job.id} attempt ${job.attempts} failed; retrying`);
    }
    return;
  }
  for (let i = 1; i <= job.steps; i++) {
    await sleep(STEP_MS);
    if (stopping) {
      // Graceful shutdown mid-job: put it back so the next worker re-runs this attempt.
      requeueStmt.run(now(), job.id);
      return;
    }
    if (i < job.steps) progressStmt.run(i, now(), job.id);
  }
  completeStmt.run(job.input.toUpperCase(), now(), job.id);
  console.log(`job ${job.id} completed`);
}

console.log('worker started');
while (!stopping) {
  let job: JobRow | undefined;
  try {
    job = claimStmt.get(now(), Date.now()) as JobRow | undefined;
  } catch (err) {
    console.error('claim failed', err);
  }
  if (!job) {
    await idle(200);
    continue;
  }
  try {
    await processJob(job);
  } catch (err) {
    console.error(`job ${job.id} error`, err);
    await idle(200);
  }
}

clearInterval(beatTimer);
db.close();
console.log('worker stopped');
process.exit(0);
EOF

