interface FieldError { field: string; message: string }

class HttpError extends Error {
  constructor(public status: number, public code: string, message: string, public fields?: FieldError[]) {
    super(message);
  }
}

function send(res: ServerResponse, status: number, body: unknown): void {
  const data = JSON.stringify(body);
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'content-length': Buffer.byteLength(data) });
  res.end(data);
}

function sendError(res: ServerResponse, err: HttpError): void {
  const error: Record<string, unknown> = { code: err.code, message: err.message };
  if (err.fields || err.code === 'invalid_request') error.fields = err.fields ?? [];
  send(res, err.status, { error });
}

const MAX_BODY = 1024 * 1024;
function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (c: Buffer) => {
      size += c.length;
      if (size > MAX_BODY) tooLarge = true;
      else chunks.push(c);
    });
    req.on('end', () => {
      if (tooLarge) reject(new HttpError(413, 'payload_too_large', 'Request body is too large.'));
      else resolve(Buffer.concat(chunks).toString('utf8'));
    });
    req.on('error', reject);
  });
}

const KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const ALLOWED = new Set(['input', 'steps', 'failAttempts']);

interface Payload { input: string; steps: number; failAttempts: number }

function validate(contentType: string | undefined, raw: string, key: string | string[] | undefined): { payload: Payload; key: string | null } {
  const fields: FieldError[] = [];
  let idemKey: string | null = null;
  if (key !== undefined) {
    if (typeof key !== 'string' || !KEY_RE.test(key)) {
      fields.push({ field: 'Idempotency-Key', message: 'Must match ^[A-Za-z0-9_-]{1,128}$.' });
    } else idemKey = key;
  }
  const mediaType = (contentType ?? '').split(';')[0]!.trim().toLowerCase();
  const isJson = mediaType === 'application/json' || /^application\/[a-z0-9.+-]*\+json$/.test(mediaType);
  if (!isJson) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
    throw new HttpError(400, 'invalid_request', 'Request is invalid.', fields);
  }
  let body: unknown;
  try {
    body = JSON.parse(raw);
  } catch {
    fields.push({ field: 'body', message: 'Body must be valid JSON.' });
    throw new HttpError(400, 'invalid_request', 'Request is invalid.', fields);
  }
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    fields.push({ field: 'body', message: 'Body must be a JSON object.' });
    throw new HttpError(400, 'invalid_request', 'Request is invalid.', fields);
  }
  const obj = body as Record<string, unknown>;
  for (const k of Object.keys(obj)) {
    if (!ALLOWED.has(k)) fields.push({ field: k, message: 'Unknown field.' });
  }
  const input = obj.input;
  if (input === undefined) fields.push({ field: 'input', message: 'Input is required.' });
  else if (typeof input !== 'string') fields.push({ field: 'input', message: 'Input must be a string.' });
  else if (input.length < 1 || input.length > 1000) fields.push({ field: 'input', message: 'Input must be 1-1000 characters.' });
  else if (input.trim() === '') fields.push({ field: 'input', message: 'Input must not be only whitespace.' });

  const intField = (name: string, min: number, max: number, def: number): number => {
    const v = obj[name];
    if (v === undefined) return def;
    if (typeof v !== 'number' || !Number.isInteger(v) || v < min || v > max) {
      fields.push({ field: name, message: `${name} must be an integer from ${min} to ${max}.` });
      return def;
    }
    return v;
  };
  const steps = intField('steps', 1, 20, 5);
  const failAttempts = intField('failAttempts', 0, 5, 0);
  if (fields.length) throw new HttpError(400, 'invalid_request', 'Request is invalid.', fields);
  return { payload: { input: input as string, steps, failAttempts }, key: idemKey };
}

const insertStmt = db.prepare(
  `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress, idempotency_key, payload, run_after, created_at, updated_at)
   VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?) RETURNING *`,
);
const byKeyStmt = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
const byIdStmt = db.prepare('SELECT * FROM jobs WHERE id = ?');
const listStmt = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const beatStmt = db.prepare('SELECT at FROM heartbeat WHERE id = 1');

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const raw = await readBody(req);
  const { payload, key } = validate(req.headers['content-type'], raw, req.headers['idempotency-key']);
  const payloadJson = JSON.stringify([payload.input, payload.steps, payload.failAttempts]);
  // DatabaseSync is synchronous, so this check-then-insert cannot interleave within the process;
  // the UNIQUE constraint guards against anything else.
  if (key !== null) {
    const existing = byKeyStmt.get(key) as (JobRow & { payload: string }) | undefined;
    if (existing) {
      if (existing.payload === payloadJson) return send(res, 200, toJob(existing));
      throw new HttpError(409, 'idempotency_conflict', 'Idempotency-Key was already used with a different payload.');
    }
  }
  const ts = new Date().toISOString();
  const row = insertStmt.get(randomUUID(), payload.input, payload.steps, payload.failAttempts, key, payloadJson, ts, ts) as unknown as JobRow;
  send(res, 201, toJob(row));
}

function methodNotAllowed(): never {
  throw new HttpError(405, 'method_not_allowed', 'Method not allowed.');
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';
  if (pathname === '/health') {
    if (method !== 'GET') methodNotAllowed();
    const row = beatStmt.get() as { at: number } | undefined;
    const up = !!row && Date.now() - row.at <= 3000;
    return send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
  }
  if (pathname === '/') {
    if (method !== 'GET' && method !== 'HEAD') methodNotAllowed();
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(method === 'HEAD' ? undefined : uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') return send(res, 200, { jobs: (listStmt.all() as unknown as JobRow[]).map(toJob) });
    if (method === 'POST') return createJob(req, res);
    methodNotAllowed();
  }
  const m = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (m) {
    if (method !== 'GET') methodNotAllowed();
    let id: string;
    try { id = decodeURIComponent(m[1]!); } catch { id = m[1]!; }
    const row = byIdStmt.get(id) as JobRow | undefined;
    if (!row) throw new HttpError(404, 'not_found', 'Job not found.');
    return send(res, 200, toJob(row));
  }
  throw new HttpError(404, 'not_found', 'Not found.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    if (res.headersSent) { res.destroy(); return; }
    if (err instanceof HttpError) return sendError(res, err);
    console.error(err);
    sendError(res, new HttpError(500, 'internal_error', 'Internal server error.'));
  });
});
server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    if (shuttingDown) return;
    shuttingDown = true;
    server.close(() => {
      db.close();
      process.exit(0);
    });
    server.closeIdleConnections();
    setTimeout(() => { server.closeAllConnections(); }, 2000).unref();
  });
}
