<body>
  <h1>Job tracker</h1>
  <form data-testid="job-form" id="job-form" novalidate>
    <label for="job-input">Input</label>
    <input id="job-input" data-testid="job-input" name="input" type="text" autocomplete="off">
    <label for="job-steps">Steps</label>
    <input id="job-steps" data-testid="job-steps" name="steps" type="number" value="5">
    <label for="job-fail-attempts">Fail attempts</label>
    <input id="job-fail-attempts" data-testid="job-fail-attempts" name="failAttempts" type="number" value="0">
    <button type="submit" data-testid="job-submit">Submit job</button>
  </form>
  <div data-testid="form-error" id="form-error" role="alert"></div>
  <h2>Jobs</h2>
  <ul data-testid="job-list" id="job-list"></ul>
<script>
(() => {
  const form = document.getElementById('job-form');
  const errorBox = document.getElementById('form-error');
  const list = document.getElementById('job-list');
  const inputEl = document.getElementById('job-input');
  const stepsEl = document.getElementById('job-steps');
  const failEl = document.getElementById('job-fail-attempts');

  function numeric(el) {
    const raw = el.value.trim();
    if (raw === '') return undefined;
    const n = Number(raw);
    return Number.isFinite(n) ? n : raw;
  }

  function showError(err) {
    errorBox.replaceChildren();
    if (!err) return;
    const p = document.createElement('p');
    p.textContent = err.message || 'Request failed.';
    errorBox.append(p);
    if (Array.isArray(err.fields) && err.fields.length) {
      const ul = document.createElement('ul');
      for (const f of err.fields) {
        const li = document.createElement('li');
        li.textContent = f.field + ': ' + f.message;
        ul.append(li);
      }
      errorBox.append(ul);
    }
  }

  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    const body = { input: inputEl.value };
    const steps = numeric(stepsEl);
    const fail = numeric(failEl);
    if (steps !== undefined) body.steps = steps;
    if (fail !== undefined) body.failAttempts = fail;
    try {
      const res = await fetch('/api/jobs', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
      const data = await res.json().catch(() => null);
      if (!res.ok) {
        showError((data && data.error) || { message: 'Request failed with status ' + res.status });
        return;
      }
      showError(null);
      inputEl.value = '';
      await refresh();
    } catch (err) {
      showError({ message: 'Network error: ' + err.message });
    }
  });

  const items = new Map();
  function makeItem(job) {
    const li = document.createElement('li');
    li.dataset.testid = 'job-item';
    li.setAttribute('data-testid', 'job-item');
    li.setAttribute('data-job-id', job.id);
    const input = document.createElement('span'); input.className = 'input';
    const status = document.createElement('span'); status.setAttribute('data-testid', 'job-status');
    const progress = document.createElement('span'); progress.setAttribute('data-testid', 'job-progress');
    const result = document.createElement('span'); result.setAttribute('data-testid', 'job-result'); result.className = 'result';
    li.append(input, status, progress, result);
    return { li, input, status, progress, result };
  }
  function setText(el, t) { if (el.textContent !== t) el.textContent = t; }
  function render(jobs) {
    const seen = new Set();
    jobs.forEach((job, i) => {
      seen.add(job.id);
      let it = items.get(job.id);
      if (!it) { it = makeItem(job); items.set(job.id, it); }
      setText(it.input, job.input);
      setText(it.status, job.status);
      it.status.className = 'status-' + job.status;
      setText(it.progress, job.progress.completed + '/' + job.progress.total);
      const r = job.status === 'completed' && job.result ? job.result.output
        : job.status === 'failed' ? (job.error || '') : '';
      setText(it.result, r);
      if (list.children[i] !== it.li) list.insertBefore(it.li, list.children[i] || null);
    });
    for (const [id, it] of items) if (!seen.has(id)) { it.li.remove(); items.delete(id); }
  }

  let inFlight = false;
  async function refresh() {
    if (inFlight) return;
    inFlight = true;
    try {
      const res = await fetch('/api/jobs');
      if (res.ok) render((await res.json()).jobs);
    } catch { /* retry on next tick */ }
    finally { inFlight = false; }
  }
  refresh();
  setInterval(refresh, 700);
})();
</script>
</body>
</html>
